\Psi(x,y,z+\Delta z) = F^{-1}\left\{ H_{prop}\cdot F\left[\Psi(x,y,z) \right] \right\}
\\[4pt]
H_{prop} = exp(-i\frac{k^2_x+k^2_y}{2\bar{k}}\Delta z), \qquad \bar{k}=n_0k_0

n_{step}(r) = \begin{cases}
n_{core,\  1}, & r<a \\
n_{cladding,\ 2}, & r \geq a
\end{cases}
\\[4pt]
n_{grin}(r)= \begin{cases}
n_1(1-2\Delta\left\{ (\frac{r}{a})^\alpha\right\})^{1/2}, & r<a \\
n_2=n_1(1-2\Delta)^{1/2}, & r \geq a
\end{cases}
\\[4pt]
\Delta=(n^2_1-n^2_2)/2n^2_1

