dt = 2*L/N;
t = (-N/2:N/2-1)*dt;
df = 1/(2*L);
[Xv,Yv] = meshgrid(t,t);
k_perp = 2*pi*(-N/2:N/2-1)*df;
r = sqrt(Xv.^2 + Yv.^2);
    info = struct('N', N, 'Lmax', max(t), 'dt', dt, 'df', df)
end

function [n1, n2, a1, L1] = components_step(n_core, n_background, a, L)
    n1 = n_core; 
    n2 = n_background; 
    L1 = L;
    a1 = a;
end

function [n3, L2] = components_CSF(n_silica, L)
    n3 = n_silica;
    L2 = L;
end

function [n4, D1, A1, a2, L3] = components_grin(n_core, Delta, alpha, a, L)
    n4 = n_core;
    D1 = Delta;
    A1 = alpha;
    L3 = L;
    a2 = a;
end


function [n5, L4] = components_material(n_material, L)
    n5 = n_material;
    L4 = L;
end

function [k0, w0] = about_Glight(lambda0, w)
    k0 = 2*pi/lambda0;
    w0 = w;
end

function RIP1 =  make_stepRI_profile(n1, n2, a1, r)
    RIP1 = n2 + double(r < a1) * (n1 - n2);
end

function RIP2 =  make_grinRI_profile(n4, D1, A1, a2, r)
    n_cladding = n4*(1-2*D1)^0.5;
    n_core = n4*sqrt(1-2*D1*((r/a2).^A1));
    RIP2=n_core.*double(r < a2)+n_cladding.*double(r >= a2); 
end

function [HP1, HP2, HP3, HP4] = Kernel_HP(k0, k_perp, n2, n3, n4, D1, n5)
    kbar_step = k0 * n2;
    kbar_CSF = k0 * n3;
        n_background_grin = n4*(1-2*D1)^0.5;
    kbar_grin = k0 * n_background_grin;
    kbar_mat = k0 * n5;

    HP1 = exp(1j*(k_perp.^2)./(sqrt(kabr_step^2-k_perp.^2)+kbar_step))
    HP2 = exp(1j*(k_perp.^2)./(sqrt(kabr_CSF^2-k_perp.^2)+kbar_CSF))
    HP3 = exp(1j*(k_perp.^2)./(sqrt(kabr_grin^2-k_perp.^2)+kbar_grin))
    HP4 = exp(1j*(k_perp.^2)./(sqrt(kabr_mat^2-k_perp.^2)+kbar_mat))
end
